function resize(){ const r=stage.getBoundingClientRect(); renderer.setSize(r.width,r.height,false); camera.aspect=r.width/r.height; camera.updateProjectionMatrix(); } addEventListener('resize', resize); resize();
let autoRotate=false, exploded=false, isolated=false, measureMode=false, measurePoints=[];
const measureGroup=new THREE.Group(); scene.add(measureGroup);
const measureLabel=document.createElement('div'); measureLabel.className='pointer-events-none absolute hidden rounded-xl border border-amber-300/40 bg-[#0e1118]/95 px-3 py-2 text-xs text-amber-100 shadow-xl'; stage.append(measureLabel);
const quoteModal=document.createElement('div'); quoteModal.className='fixed inset-0 z-50 hidden items-center justify-center bg-black/70 p-6 backdrop-blur-sm'; quoteModal.innerHTML='<form class="w-full max-w-lg rounded-3xl border border-white/10 bg-[#0e1118] p-6 shadow-2xl"><div class="flex items-center justify-between"><div><p class="text-xs font-semibold uppercase tracking-[.2em] text-emerald-300">Product enquiry</p><h2 class="mt-1 text-xl font-medium text-white">Request a quote</h2></div><button type="button" class="close-quote text-2xl text-slate-500 hover:text-white">×</button></div><div class="mt-6 grid gap-4 sm:grid-cols-2"><input name="name" required placeholder="Your name" class="rounded-xl border border-white/10 bg-black/20 px-4 py-3 text-sm text-white outline-none"><input name="email" type="email" required placeholder="Email address" class="rounded-xl border border-white/10 bg-black/20 px-4 py-3 text-sm text-white outline-none"><input name="company" placeholder="Company (optional)" class="rounded-xl border border-white/10 bg-black/20 px-4 py-3 text-sm text-white outline-none sm:col-span-2"><textarea name="message" rows="4" placeholder="Tell us what you need..." class="rounded-xl border border-white/10 bg-black/20 px-4 py-3 text-sm text-white outline-none sm:col-span-2"></textarea></div><p class="quote-error mt-3 hidden text-sm text-rose-300"></p><button class="mt-5 w-full rounded-xl bg-emerald-300 px-4 py-3 text-sm font-semibold text-slate-950 hover:bg-emerald-200">Send request</button></form>'; document.body.append(quoteModal);
let wireframeEnabled=false, backgroundIndex=0;
const backgrounds=[0x111827,0x172033,0xf1f5f9,0x102a2a,0x241b33];
function meshMaterials(){ return modelParts.flatMap(part=>Array.isArray(part.material)?part.material:[part.material]); }
function focusObject(object){ if(!object)return; const box=new THREE.Box3().setFromObject(object), center=box.getCenter(new THREE.Vector3()), size=box.getSize(new THREE.Vector3()), distance=Math.max(size.x,size.y,size.z)*2.2; camera.position.copy(center).add(new THREE.Vector3(distance*.8,distance*.6,distance)); controls.target.copy(center); controls.update(); }
function standardView(axis){ if(!model)return; const box=new THREE.Box3().setFromObject(model), center=box.getCenter(new THREE.Vector3()), size=box.getSize(new THREE.Vector3()), distance=Math.max(size.x,size.y,size.z)*2.4; const positions={front:new THREE.Vector3(0,0,distance),top:new THREE.Vector3(0,distance,0),side:new THREE.Vector3(distance,0,0)}; camera.position.copy(center).add(positions[axis]); controls.target.copy(center); controls.update(); }
focusTool.onclick=()=>{ if(selectedParts.length)focusObject(selectedParts.length===1?selectedParts[0]:model); else focusObject(model); };
viewFrontTool.onclick=()=>standardView('front');
viewTopTool.onclick=()=>standardView('top');
viewSideTool.onclick=()=>standardView('side');
wireframeTool.onclick=event=>{ wireframeEnabled=!wireframeEnabled; meshMaterials().forEach(material=>material.wireframe=wireframeEnabled); event.currentTarget.textContent=wireframeEnabled?'Solid view':'Wireframe'; event.currentTarget.classList.toggle('bg-cyan-300/20',wireframeEnabled); };
backgroundTool.onclick=()=>{ backgroundIndex=(backgroundIndex+1)%backgrounds.length; scene.background.setHex(backgrounds[backgroundIndex]); backgroundTool.textContent=['Background','Blue background','Light background','Teal background'][backgroundIndex]; };
function frame(){ renderer.setAnimationLoop(()=>{ if(autoRotate&&model)model.rotation.y+=.0025; controls.update(); if(selectionHelper.visible) selectionHelper.update(); updateHotspots(); updateMeasurementLabel(); renderer.render(scene,camera); }); } frame();
function readablePartName(mesh, index){ const clean=value=>String(value||'').replace(/^(object|mesh|node|primitive|geometry)[_.\- ]*\d*$/i,'').replace(/[_.\-]+/g,' ').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/\s+/g,' ').trim(); const meshName=clean(mesh.name); const materialName=clean(mesh.material?.name); const parentName=clean(mesh.parent?.name); const generic=!meshName || /^(cube|sphere|cylinder|plane|circle|box|shape)\s*\d*$/i.test(meshName); const label=generic ? (materialName || parentName || `Part ${index+1}`) : meshName; return label.replace(/\b\w/g, letter=>letter.toUpperCase()); }
function listParts(){ modelParts=[]; model.traverse(o=>{ if(o.isMesh){ o.userData.baseColor=o.material.color?.clone(); o.userData.displayName=readablePartName(o,modelParts.length); modelParts.push(o); }}); document.querySelector('#part-count').textContent=modelParts.length; partsEl.innerHTML=modelParts.map((m,i)=>`<button data-part="${i}" class="part flex w-full items-center justify-between rounded-xl px-3 py-2 text-left text-sm text-slate-400 hover:bg-white/5"><span>${m.userData.displayName}</span><span class="text-[10px] text-slate-600">${m.material?.name && !/^material[_.\-]?\d*$/i.test(m.material.name) ? m.material.name : 'surface'}</span></button>`).join(''); partsEl.querySelectorAll('.part').forEach((b,i)=>b.onclick=()=>select(modelParts[i],b)); }
function setMeshHighlight(mesh, active){ if(!mesh?.material)return; const materials=Array.isArray(mesh.material)?mesh.material:[mesh.material]; mesh.userData.baseEmissives ??= materials.map(material=>({ color:material.emissive?.clone(), intensity:material.emissiveIntensity ?? 1 })); materials.forEach((material,index)=>{ if(!material.emissive)return; if(active){ material.emissive.set(0x22d3ee); material.emissiveIntensity=.2; } else { const base=mesh.userData.baseEmissives[index]; if(base.color)material.emissive.copy(base.color); material.emissiveIntensity=base.intensity; } }); }
function updateSelectionStatus(){ const status=document.querySelector('#selection-status'); if(status)status.textContent=selectedParts.length+' part'+(selectedParts.length===1?'':'s')+' selected'; if(selectedPartBadge){ if(selectedParts.length===1){ selectedPartBadge.textContent='Selected part · '+(selectedParts[0].userData.displayName||'Model part'); selectedPartBadge.classList.remove('hidden'); } else if(selectedParts.length>1){ selectedPartBadge.textContent='Selected · '+selectedParts.length+' parts'; selectedPartBadge.classList.remove('hidden'); } else { selectedPartBadge.classList.add('hidden'); } } }
function select(mesh, button){ if(!mesh)return; selectedParts.forEach(part=>setMeshHighlight(part,false)); selectedParts=[mesh]; setMeshHighlight(mesh,true); partsEl.querySelectorAll('.part').forEach(b=>b.classList.remove('mesh-active')); button?.classList.add('mesh-active'); selectionHelper.visible=false; const firstMaterial=selectedMaterials()[0]; if(firstMaterial?.color)document.querySelector('#color').value='#'+firstMaterial.color.getHexString(); updateSelectionStatus(); }
function selectAll(){ selectedParts.forEach(part=>setMeshHighlight(part,false)); selectedParts=[...modelParts]; selectedParts.forEach(part=>setMeshHighlight(part,true)); selectionHelper.visible=false; partsEl.querySelectorAll('.part').forEach(b=>b.classList.add('mesh-active')); updateSelectionStatus(); }
function deselectAll(){ selectedParts.forEach(part=>setMeshHighlight(part,false)); selectedParts=[]; selectionHelper.visible=false; partsEl.querySelectorAll('.part').forEach(b=>b.classList.remove('mesh-active')); updateSelectionStatus(); }
function addSelectionControls(){ const controls=document.createElement('div'); controls.className='mb-2 space-y-2'; controls.innerHTML='<div class="flex items-center justify-between"><span id="selection-status" class="text-xs text-cyan-300">No parts selected</span><button type="button" class="deselect-parts text-[11px] text-slate-500 hover:text-white">Deselect</button></div><input type="search" placeholder="Search parts..." class="part-search w-full rounded-xl border border-white/10 bg-black/20 px-3 py-2 text-xs text-white outline-none placeholder:text-slate-600 focus:border-cyan-300/50"><button type="button" class="select-all-parts w-full rounded-lg bg-white/10 px-2 py-2 text-[11px] text-slate-300 hover:bg-cyan-300/20">Select all parts</button><p class="text-[10px] leading-4 text-slate-500">Selection stays active while you edit. Click empty space or press Esc to clear.</p>'; partsEl.prepend(controls); controls.querySelector('.select-all-parts').onclick=selectAll; controls.querySelector('.deselect-parts').onclick=deselectAll; controls.querySelector('.part-search').oninput=event=>{ const query=event.target.value.toLowerCase(); partsEl.querySelectorAll('.part').forEach(button=>button.classList.toggle('hidden',!button.textContent.toLowerCase().includes(query))); }; }
function selectedMaterials(){ return selectedParts.flatMap(part=>Array.isArray(part.material)?part.material:[part.material]); }
function ensureTextureCoordinates(mesh){ const geometry=mesh.geometry; if(geometry.attributes.uv)return false; const positions=geometry.attributes.position; if(!positions)return false; if(!geometry.attributes.normal)geometry.computeVertexNormals(); const normals=geometry.attributes.normal; geometry.computeBoundingBox(); const bounds=geometry.boundingBox, min=bounds.min, max=bounds.max, size=new THREE.Vector3().subVectors(max,min); const uv=[]; const safe=(value)=>Math.max(value,0.000001); for(let index=0;index<positions.count;index++){ const x=positions.getX(index), y=positions.getY(index), z=positions.getZ(index), nx=Math.abs(normals.getX(index)), ny=Math.abs(normals.getY(index)), nz=Math.abs(normals.getZ(index)); let u,v,minU,maxU,minV,maxV; if(nx>=ny&&nx>=nz){u=z;v=y;minU=min.z;maxU=max.z;minV=min.y;maxV=max.y;} else if(ny>=nx&&ny>=nz){u=x;v=z;minU=min.x;maxU=max.x;minV=min.z;maxV=max.z;} else {u=x;v=y;minU=min.x;maxU=max.x;minV=min.y;maxV=max.y;} uv.push((u-minU)/safe(maxU-minU),1-(v-minV)/safe(maxV-minV)); } geometry.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2)); geometry.attributes.uv.needsUpdate=true; mesh.userData.generatedUv=true; return true; }
function captureOriginalAppearance(){ modelParts.forEach(part=>{ ensureTextureCoordinates(part); part.userData.originalPosition=part.position.clone(); part.userData.explodeDirection=part.position.clone().add(new THREE.Vector3(.1,.1,.1)).normalize(); const sourceMaterials=Array.isArray(part.material)?part.material:[part.material]; const clonedMaterials=sourceMaterials.map(material=>material.clone()); part.material=Array.isArray(part.material)?clonedMaterials:clonedMaterials[0]; clonedMaterials.forEach(material=>{ material.userData.originalColor=material.color?.clone(); material.userData.originalMap=material.map; }); }); }
function prepareTexture(texture){ texture.colorSpace=THREE.SRGBColorSpace; texture.flipY=false; texture.wrapS=THREE.RepeatWrapping; texture.wrapT=THREE.RepeatWrapping; texture.anisotropy=renderer.capabilities.getMaxAnisotropy(); texture.needsUpdate=true; return texture; }
function applyTexture(texture,url){ let applied=0, autoMapped=0; selectedParts.forEach(part=>{ if(!part.geometry?.attributes?.uv){ if(!ensureTextureCoordinates(part))return; autoMapped++; } const materials=Array.isArray(part.material)?part.material:[part.material]; materials.forEach(material=>{ const materialTexture=texture.clone(); materialTexture.needsUpdate=true; material.map=materialTexture; material.userData.appliedTextureUrl=url; material.needsUpdate=true; applied++; }); }); return {applied,autoMapped}; }
window.applyModelTexture=(url,name)=>{ if(!selectedParts.length){ toast('Select one or more model parts first.'); return; } new THREE.TextureLoader().load(url,t=>{ const result=applyTexture(prepareTexture(t),url); materialsPanel.querySelector('#texture-status').textContent=result.applied?'Applied: '+name+(result.autoMapped?' · Auto-mapped':''):'Texture could not be mapped'; }, undefined, error=>{ materialsPanel.querySelector('#texture-status').textContent='Texture could not be loaded'; console.error('Texture could not be loaded',error); }); };
materialsPanel.querySelector('#apply-texture').onclick=()=>{ if(pendingTexture)window.applyModelTexture(pendingTexture.url,pendingTexture.name); };
function applyVariant(variant){ const parts=variant?.configuration?.parts||{}; Object.entries(parts).forEach(([index,state])=>{ const part=modelParts[Number(index)]; if(!part)return; const materials=Array.isArray(part.material)?part.material:[part.material]; materials.forEach(material=>{ if(state.color&&material.color)material.color.set(state.color); if(state.texture&&part.geometry?.attributes?.uv)new THREE.TextureLoader().load(state.texture,texture=>{ prepareTexture(texture); material.map=texture; material.userData.appliedTextureUrl=state.texture; material.needsUpdate=true; }); }); }); variantPanel.querySelector('#variant-status').textContent='Applied'; }
variantPanel.querySelector('#apply-variant').onclick=()=>{ if(pendingVariant)applyVariant(pendingVariant); };
materialsPanel.querySelector('#texture-search').oninput=event=>{ const query=event.target.value.toLowerCase(); textureLibraryEl.querySelectorAll('.texture-option').forEach(button=>button.classList.toggle('hidden',!button.textContent.toLowerCase().includes(query))); };
materialsPanel.querySelector('#texture-scale').oninput=event=>{ const scale=Number(event.target.value); selectedMaterials().forEach(material=>{ if(material.map)material.map.repeat.set(scale,scale); }); };
materialsPanel.querySelector('#clear-applied-texture').onclick=()=>{ selectedMaterials().forEach(material=>{ material.map=null; material.needsUpdate=true; }); materialsPanel.querySelector('#texture-status').textContent='Texture cleared'; };
materialsPanel.querySelector('#reset-appearance').onclick=()=>{ modelParts.forEach(part=>{ const materials=Array.isArray(part.material)?part.material:[part.material]; materials.forEach(material=>{ if(material.userData.originalColor)material.color.copy(material.userData.originalColor); material.map=material.userData.originalMap||null; material.needsUpdate=true; }); }); pendingTexture=null; materialsPanel.querySelector('#texture-status').textContent='Appearance reset'; };
new GLTFLoader().load(@json($modelUrl), async gltf=>{ model=gltf.scene; const box=new THREE.Box3().setFromObject(model), center=box.getCenter(new THREE.Vector3()), size=box.getSize(new THREE.Vector3()), scale=2.5/Math.max(size.x,size.y,size.z); model.scale.setScalar(scale); model.position.sub(center.multiplyScalar(scale)); scene.add(model); listParts(); captureOriginalAppearance(); addSelectionControls(); const hashConfig=window.location.hash.startsWith('#config=')?decodeConfiguration(window.location.hash.slice(8)):null; const localConfig=JSON.parse(localStorage.getItem('model-config-{{ $item->slug }}')||'null'); const queryToken=new URLSearchParams(window.location.search).get('configuration'); const savedConfig=queryToken?await loadServerConfiguration(queryToken):null; restoreConfiguration(savedConfig?.configuration||hashConfig||localConfig); }, progress=>{ if(progress.lengthComputable){ const percentEl=document.querySelector('#loading-percent'); if(percentEl)percentEl.textContent=' '+Math.round(progress.loaded/progress.total*100)+'%'; } }, e=>{ partsEl.innerHTML='<p class="px-3 py-2 text-sm text-rose-300">Could not load this GLB file.</p>'; loadingOverlay.querySelector('p').textContent='Could not load this model.'; console.error(e); });
stage.addEventListener('pointerdown', e=>{ if(!model||e.target.closest('button'))return; const rect=renderer.domElement.getBoundingClientRect(); pointer.x=((e.clientX-rect.left)/rect.width)*2-1; pointer.y=-((e.clientY-rect.top)/rect.height)*2+1; raycaster.setFromCamera(pointer,camera); const hit=raycaster.intersectObject(model,true)[0]; if(hit){ const index=modelParts.indexOf(hit.object); select(hit.object,partsEl.querySelector(`[data-part="${index}"]`)); } else { deselectAll(); } });
addEventListener('keydown', event=>{ if(event.target.closest('input,textarea,select'))return; if(event.key==='Escape'){ deselectAll(); toggleShortcuts(false); } else if(event.key==='?'){ toggleShortcuts(true); } else if(event.key==='r'||event.key==='R'){ document.querySelector('#reset').click(); } else if(event.key==='f'||event.key==='F'){ document.querySelector('#fullscreen').click(); } else if(event.key==='w'||event.key==='W'){ wireframeTool.click(); } else if(event.key==='e'||event.key==='E'){ viewerTools.querySelector('#explode-model').click(); } else if(event.key==='a'||event.key==='A'){ viewerTools.querySelector('#auto-rotate').click(); } else if(event.key==='i'||event.key==='I'){ viewerTools.querySelector('#isolate-part').click(); } });
stage.addEventListener('click', e=>{ if(!measureMode||!model||e.target.closest('button'))return; const rect=renderer.domElement.getBoundingClientRect(); pointer.x=((e.clientX-rect.left)/rect.width)*2-1; pointer.y=-((e.clientY-rect.top)/rect.height)*2+1; raycaster.setFromCamera(pointer,camera); const hit=raycaster.intersectObject(model,true)[0]; if(!hit)return; if(measurePoints.length===2){ measurePoints=[]; measureGroup.clear(); } measurePoints.push(hit.point.clone()); if(measurePoints.length===2){ const distance=measurePoints[0].distanceTo(measurePoints[1]); const geometry=new THREE.BufferGeometry().setFromPoints(measurePoints); const line=new THREE.Line(geometry,new THREE.LineBasicMaterial({color:0xfbbf24,depthTest:false})); line.renderOrder=20; measureGroup.add(line); measureLabel.textContent='Distance: '+distance.toFixed(3)+' model units'; measureLabel.classList.remove('hidden'); } });
function updateMeasurementLabel(){ if(measurePoints.length!==2)return; const midpoint=measurePoints[0].clone().lerp(measurePoints[1],.5).project(camera); const rect=stage.getBoundingClientRect(); measureLabel.style.left=((midpoint.x+1)/2*rect.width)+'px'; measureLabel.style.top=((-midpoint.y+1)/2*rect.height)+'px'; }
viewerTools.querySelector('#measure-model').onclick=event=>{ measureMode=!measureMode; event.currentTarget.classList.toggle('bg-amber-300/20',measureMode); event.currentTarget.textContent=measureMode?'Click two points':'Measure'; if(!measureMode){ measurePoints=[]; measureGroup.clear(); measureLabel.classList.add('hidden'); } };
quoteButton.onclick=()=>{ quoteModal.classList.remove('hidden'); quoteModal.classList.add('flex'); };
quoteModal.querySelector('.close-quote').onclick=()=>{ quoteModal.classList.add('hidden'); quoteModal.classList.remove('flex'); };
quoteModal.querySelector('form').onsubmit=async event=>{ event.preventDefault(); const form=event.currentTarget, error=quoteModal.querySelector('.quote-error'), submit=form.querySelector('button[type="submit"]'); submit.disabled=true; error.classList.add('hidden'); try { const response=await fetch(@json(route('items.quote-requests.store',$item->slug)),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':@json(csrf_token())},body:JSON.stringify({name:form.name.value,email:form.email.value,company:form.company.value,message:form.message.value,configuration:configurationState()})}); if(!response.ok)throw new Error('Request could not be sent'); form.innerHTML='<div class="py-8 text-center"><div class="text-4xl text-emerald-300">✓</div><h2 class="mt-3 text-xl font-medium text-white">Request received</h2><p class="mt-2 text-sm text-slate-400">Our team will review your configuration and contact you soon.</p></div>'; } catch(exception) { error.textContent='Please check your details and try again.'; error.classList.remove('hidden'); submit.disabled=false; } };
document.querySelector('#apply-color').onclick=()=>{ const color=document.querySelector('#color').value; selectedMaterials().forEach(material=>{ material.color?.set(color); material.userData.appliedColor=color; material.needsUpdate=true; }); document.querySelector('#texture-status').textContent='Color applied: '+color; };
document.querySelector('#clear-texture')?.addEventListener('click',()=>{ selectedMaterials().forEach(material=>{material.map=null;material.needsUpdate=true;}); document.querySelector('#clear-texture')?.classList.add('hidden'); });
document.querySelector('#reset').onclick=()=>{ camera.position.copy(originalCamera); controls.target.set(0,.7,0); controls.update(); isolated=false; exploded=false; modelParts.forEach(part=>part.visible=true); setExplode(0); viewerTools.querySelector('#isolate-part').textContent='Isolate selected'; viewerTools.querySelector('#explode-model').classList.remove('bg-cyan-300/20'); };
function configurationState(){ return { version:1, item:'{{ $item->slug }}', parts:modelParts.map((part,index)=>({ index, visible:part.visible, materials:(Array.isArray(part.material)?part.material:[part.material]).map(material=>({ color:material.color?.getHexString(), texture:material.userData.appliedTextureUrl||null })) })) }; }
function encodeConfiguration(state){ return btoa(unescape(encodeURIComponent(JSON.stringify(state)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); }
function decodeConfiguration(value){ try { const padded=value.replace(/-/g,'+').replace(/_/g,'/')+'==='.slice((value.length+3)%4); return JSON.parse(decodeURIComponent(escape(atob(padded)))); } catch(error) { console.error('Invalid model configuration',error); return null; } }
async function saveConfiguration(){ const state=configurationState(); localStorage.setItem('model-config-{{ $item->slug }}',JSON.stringify(state)); const response=await fetch(@json(route('items.configurations.store',$item->slug)),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':@json(csrf_token())},body:JSON.stringify({name:'My configuration',configuration:state})}); if(!response.ok)throw new Error('Configuration could not be saved'); const data=await response.json(); const button=document.querySelector('#save-config'); button.textContent='Configuration saved'; setTimeout(()=>button.textContent='Save configuration',1800); return data; }
async function loadServerConfiguration(token){ try { const response=await fetch(@json(route('items.configurations.show',[$item->slug,'CONFIGURATION_TOKEN'])).replace('CONFIGURATION_TOKEN',encodeURIComponent(token)),{headers:{'Accept':'application/json'}}); return response.ok?await response.json():null; } catch(error) { console.error('Configuration could not be loaded',error); return null; } }
async function shareConfiguration(){ try { const data=await saveConfiguration(); await navigator.clipboard.writeText(data.url); const button=document.querySelector('#share-config'); button.textContent='Link copied'; setTimeout(()=>button.textContent='Share configuration',1800); } catch(error) { const url=new URL(window.location.href); url.hash='config='+encodeConfiguration(configurationState()); window.prompt('Copy this configuration link:',url.toString()); } }
function restoreConfiguration(state){ if(!state?.parts)return; state.parts.forEach(saved=>{ const part=modelParts[saved.index]; if(!part)return; part.visible=saved.visible!==false; const materials=Array.isArray(part.material)?part.material:[part.material]; saved.materials?.forEach((materialState,index)=>{ const material=materials[index]; if(!material)return; if(materialState.color&&material.color)material.color.set('#'+materialState.color); if(materialState.texture&&part.geometry?.attributes?.uv)new THREE.TextureLoader().load(materialState.texture,texture=>{ prepareTexture(texture); material.map=texture; material.userData.appliedTextureUrl=materialState.texture; material.needsUpdate=true; }); }); }); }
function setExplode(amount){ if(!model)return; modelParts.forEach(part=>{ part.position.copy(part.userData.originalPosition); if(amount){ const direction=part.userData.explodeDirection||new THREE.Vector3((part.position.x||0)+.1,(part.position.y||0)+.1,(part.position.z||0)+.1).normalize(); part.position.addScaledVector(direction,amount); } }); }
viewerTools.querySelector('#auto-rotate').onclick=event=>{ autoRotate=!autoRotate; event.currentTarget.classList.toggle('bg-cyan-300/20',autoRotate); };
viewerTools.querySelector('#isolate-part').onclick=()=>{ if(!selectedParts.length){ toast('Select a model part first.'); return; } isolated=!isolated; modelParts.forEach(part=>part.visible=!isolated||selectedParts.includes(part)); viewerTools.querySelector('#isolate-part').textContent=isolated?'Show all parts':'Isolate selected'; };
viewerTools.querySelector('#explode-model').onclick=event=>{ exploded=!exploded; setExplode(exploded ? .45 : 0); event.currentTarget.classList.toggle('bg-cyan-300/20',exploded); };
viewerTools.querySelector('#save-config').onclick=saveConfiguration;
viewerTools.querySelector('#share-config').onclick=shareConfiguration;
document.querySelector("#fullscreen").onclick=()=>{ document.fullscreenElement ? document.exitFullscreen() : stage.requestFullscreen?.(); }; document.querySelector("#share").onclick=async()=>{ try { if(navigator.share){ await navigator.share({title:document.title,url:window.location.href}); } else { await navigator.clipboard.writeText(window.location.href); const button=document.querySelector("#share"); button.textContent="Link copied"; setTimeout(()=>button.textContent="Share",1800); } } catch(error) { if(error.name !== "AbortError") console.error(error); } }; function download(type){ const link=document.createElement('a'); link.download='{{ $item->slug }}.'+(type==='image/jpeg'?'jpg':'png'); link.href=renderer.domElement.toDataURL(type,.92); link.click(); } document.querySelector('#png').onclick=()=>download('image/png'); document.querySelector('#jpeg').onclick=()=>download('image/jpeg');
</script></body></html>
